using TORSEPAN.Panel.Models;namespace TORSEPAN.Panel.Services.Api;
public sealed class AccountingService(ApiClient api){public Task<AccountingSummaryDto?> SummaryAsync()=>api.GetAsync<AccountingSummaryDto>("accounting/summary");public async Task<List<AccountingPartyDto>> PartiesAsync()=>await api.GetAsync<List<AccountingPartyDto>>("accounting/parties")??[];public async Task<List<AccountingDocumentDto>> DocumentsAsync(Guid? partyId=null)=>await api.GetAsync<List<AccountingDocumentDto>>("accounting/documents"+(partyId.HasValue?$"?partyId={partyId}":""))??[];public Task AddPartyAsync(string name,string? company,string? phone,string? notes)=>api.PostAsync<object,object?>("accounting/parties",new{name,company,phone,notes});public Task AddDocumentAsync(int type,string title,decimal total,decimal paid,Guid? partyId,DateTime? due,string? notes)=>api.PostAsync<object,object?>("accounting/documents",new{type,title,TotalAmount=total,PaidAmount=paid,partyId,DueDate=due,notes});public Task AddPaymentAsync(Guid id,decimal amount)=>api.PostAsync<object,object?>($"accounting/documents/{id}/payments",new{amount});}
